package com.automation.service.ai;

import java.util.List;

/**
 * What a person needs to set up an AI provider on their machine — read by the
 * installer ({@code scripts/lib/provider-catalog.generated.sh}, generated by ProviderCatalogTest).
 * This way the installer names all providers as equals instead of hard-wiring Claude (2255f2ee).
 * The same data feeds the UI's status display ({@code AiProviderStatusService},
 * f5a273ae): program found, login found, otherwise the command.
 *
 * @param cli         program name on the PATH
 * @param install     install command or path
 * @param login       the command to log in — only the command, so that it lands in the clipboard
 * @param loginFiles  files relative to {@code $HOME} whose presence indicates a login;
 *                    {@code file:pattern} means the file must contain the pattern. A heuristic:
 *                    installer and status display see that a login exists, not whether it is valid.
 * @param loginEnv    environment variables of which one that is set (non-empty) also counts
 *                    as a login, e.g. an API key or OAuth token (0b1a3ae7). Only whether
 *                    it is set is checked; the value is never printed.
 * @param loginDir    directory relative to {@code $HOME} in which the CLI stores its login and which
 *                    {@code loginDirEnv} redirects; null if no variable redirects it
 * @param loginDirEnv environment variable that redirects {@code loginDir} ({@code CODEX_HOME} …). Container
 *                    instances set it (scripts/lib/host-mounts.sh), the status display then looks for
 *                    login files under {@code loginDir} there. The installer reads neither:
 *                    it runs on the machine where the directories are in their place.
 * @param loginNote   what remains to be done after the command, as a key instead of text (eab43a8b): installer
 *                    ({@code M_login_note_<key>} in scripts/lib/i18n) and UI
 *                    ({@code aiProviderStatus.loginNotes}) translate it — an English sentence here
 *                    also appeared in the German UI. null if the command says everything.
 */
public record ProviderSetup(String cli, String install, String login, List<String> loginFiles,
                            List<String> loginEnv, String loginDir, String loginDirEnv, String loginNote) {
    public ProviderSetup {
        loginFiles = List.copyOf(loginFiles);
        loginEnv = List.copyOf(loginEnv);
    }

    /** A provider whose login command says everything. */
    public ProviderSetup(String cli, String install, String login, List<String> loginFiles, List<String> loginEnv,
                         String loginDir, String loginDirEnv) {
        this(cli, install, login, loginFiles, loginEnv, loginDir, loginDirEnv, null);
    }

    /** A provider without a redirectable login directory. */
    public ProviderSetup(String cli, String install, String login, List<String> loginFiles, List<String> loginEnv) {
        this(cli, install, login, loginFiles, loginEnv, null, null, null);
    }
}
